compile.workshop:
variables {
    global:
        0: Mode
        1: Text
        2: Name
        3: Items
}

rule ("chained else line break") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(Text, If-Then-Else(Compare(Global.Mode, ==, 0), Custom String("{0} is idle", Global.Name), If-Then-Else(Compare(Global.Mode, ==, 1), Custom String("{0} is running", Global.Name), Custom String("{0} is {1}", Global.Name, Global.Mode))));
        Set Global Variable(Items, Array(If-Then-Else(Compare(Global.Mode, ==, 0), Custom String("a"), Custom String("b"))));
    }
}

